reproducibility.recursiveTreeVerifier:
function verifyRecursiveTree(t,verifyTree,utf8,sha1){
 if(t.truncated||!Array.isArray(t.tree))throw Error("truncated recursive tree");
 const byPath=new Map(),groups=new Map([["",[]]]),directorySha=new Map([["",t.sha]]),typeCounts={};
 for(const e of t.tree){
  if(!e.path||e.path.startsWith("/")||e.path.endsWith("/")||e.path.split("/").some(x=>!x||x==="."||x==="..")||byPath.has(e.path))throw Error("invalid/duplicate path "+e.path);
  byPath.set(e.path,e);typeCounts[e.type]=(typeCounts[e.type]||0)+1;
  if(e.type==="tree"){groups.set(e.path,[]);directorySha.set(e.path,e.sha);}
 }
 for(const e of t.tree){
  const slash=e.path.lastIndexOf("/"),parent=slash<0?"":e.path.slice(0,slash),name=e.path.slice(slash+1);
  if(!groups.has(parent))throw Error("missing parent or prefix collision "+e.path);
  groups.get(parent).push({...e,path:name});
 }
 const verified=[];
 for(const [path,children]of groups){const sha=directorySha.get(path);const v=verifyTree({sha,truncated:false,tree:children},utf8,sha1);verified.push({path,sha,children:children.length,verified:v.verified});}
 const leaves=t.tree.filter(e=>e.type!=="tree").map(({path,mode,type,sha,size})=>({path,mode,type,sha,...(size===undefined?{}:{size})})).sort((a,b)=>a.path.localeCompare(b.path,"en"));
 return {root:t.sha,entries:t.tree.length,leafCount:leaves.length,directoryCount:groups.size,duplicatePaths:0,missingParents:0,prefixCollisions:0,typeCounts,allTreeHashesVerified:true,verifiedDirectories:verified,leaves};
}

reproducibility.treeHasherFromPriorProof:
function verifyTree(t,utf8,sha1){
 if(t.truncated||!Array.isArray(t.tree))throw Error("truncated/missing tree");
 const encoded=t.tree.map(e=>({e,key:utf8(e.path+(e.type==="tree"?"/":""))})).sort((a,b)=>{const n=Math.min(a.key.length,b.key.length);for(let i=0;i<n;i++)if(a.key[i]!==b.key[i])return a.key[i]-b.key[i];return a.key.length-b.key.length});
 let b=[];for(const {e} of encoded){b.push(...utf8(e.mode.replace(/^0+/,"")+" "+e.path+"\0"));for(let i=0;i<40;i+=2)b.push(parseInt(e.sha.slice(i,i+2),16));}
 const actual=sha1(utf8("tree "+b.length+"\0").concat(b));if(actual!==t.sha)throw Error("tree SHA mismatch "+t.sha+" != "+actual);
 return {sha:t.sha,verified:true,entries:t.tree.map(({path,mode,type,sha,size})=>({path,mode,type,sha,...(size===undefined?{}:{size})}))};
}
